+function cacheShare(cacheTokens, inputTokens) {
+  const cache = Number(cacheTokens || 0);
+  const input = Number(inputTokens || 0);
+  if (!cache || !input) return '0%\u00a0cached';
+  return `${Math.round((cache / input) * 100)}%\u00a0cached`;
+}
+
+function keepTogether(value, label) {
+  return `${value}\u00a0${label.replaceAll(' ', '\u00a0')}`;
+}
