+function setCostMeta(id, fullyPricedCount, modelCount, detail = '', partialCount = 0) {
+  const el = document.getElementById(id);
+  if (!el) return;
+  const fully = Number(fullyPricedCount || 0);
+  const total = Number(modelCount || 0);
+  const partial = Number(partialCount || 0);
+  const hasFully = fully > 0;
+  const hasPartial = partial > 0;
+  let visible;
+  if (hasFully && hasPartial) {
+    visible = `${fully} full · ${partial} partial`;
+  } else if (hasFully) {
+    visible = `${fully}/${total} priced`;
+  } else if (hasPartial) {
+    visible = `${partial} partial`;
+  } else {
+    visible = 'No pricing';
+  }
+  const detailText = String(detail || '');
+  const tooltipId = `${id}-tooltip`;
+  el.innerHTML = `
+    <span class="estimate-meta">
+      ${hasPartial ? '<span class="estimate-badge">Partial estimate</span>' : ''}
+      <span class="estimate-coverage">${escapeHtml(visible)}</span>
+    </span>
+    ${detailText ? `
+      <span class="meta-info-wrap">
+        <button
+          type="button"
+          class="meta-info"
+          aria-label="More information: ${hasPartial ? 'partial estimate' : escapeHtml(visible)}"
+          aria-expanded="false"
+          aria-describedby="${escapeHtml(tooltipId)}"
+        >i</button>
+        <span class="meta-tooltip" id="${escapeHtml(tooltipId)}" role="tooltip">${escapeHtml(detailText)}</span>
+      </span>
+    ` : ''}
+  `;
+  bindMetaInfoInteractions(el);
+}
